<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { MapPin, Search } from '@lucide/vue'
import TravelModal from './TravelModal.vue'
import TravelMap from './TravelMap.vue'
import type { Place, PlaceCategory } from '../stores/places'
import type { CreatePlaceInput } from '../api/places'
import { apiRequest } from '../api/client'
import { safeSource } from './model'
const props=defineProps<{place?:Place|null;busy:boolean;initial?:Partial<CreatePlaceInput>;apiError?:string}>()
const emit=defineEmits<{close:[];save:[input:CreatePlaceInput]}>()
const source=props.place||props.initial
const name=ref(source?.name||''),city=ref(source?.city||''),address=ref(source?.address||''),category=ref<PlaceCategory>(source?.category||'景点'),tags=ref(source?.tags?.join('，')||''),notes=ref(source?.notes||''),url=ref(source?.sourceUrl||'')
const longitude=ref<number|string>(source?.longitude??''),latitude=ref<number|string>(source?.latitude??''),showMap=ref(false),error=ref(''),searching=ref(false)
const results=ref<Array<{name:string;city?:string;address:string;longitude:number;latitude:number}>>([])
const searchAvailable=ref(false),searchProvider=ref('Photon')
onMounted(async()=>{try{const status=await apiRequest<{searchAvailable:boolean;provider?:string}>('/api/v1/maps/status');searchAvailable.value=status.searchAvailable;searchProvider.value=status.provider||'Photon'}catch{/* Manual map selection is available independently. */}})
const picked=computed(()=>longitude.value!==''&&latitude.value!==''&&Number.isFinite(Number(longitude.value))&&Number.isFinite(Number(latitude.value))?{longitude:Number(longitude.value),latitude:Number(latitude.value)}:null)
async function search(){if(searching.value)return;searching.value=true;error.value='';try{results.value=await apiRequest('/api/v1/maps/search?'+new URLSearchParams({query:[city.value,name.value].filter(Boolean).join(' ')}));if(!results.value.length)error.value='没有找到匹配地点，可以手动填写或在地图上选点'}catch(cause){error.value=cause instanceof Error?cause.message:'搜索失败'}finally{searching.value=false}}
function select(result:(typeof results.value)[number]){if(!name.value.trim())name.value=result.name.slice(0,180);address.value=result.address.slice(0,300);if(!city.value.trim()&&result.city)city.value=result.city.slice(0,120);longitude.value=result.longitude;latitude.value=result.latitude;showMap.value=true;results.value=[]}
function save(){error.value='';const list=tags.value.split(/[,，、]/).map(item=>item.trim()).filter(Boolean);if(list.length>20||list.some(item=>item.length>40)){error.value='最多 20 个标签，每个不超过 40 字';return}
  if(url.value&&!safeSource(url.value)){error.value='来源链接需要完整的 HTTPS 地址';return}
  if((longitude.value==='')!==(latitude.value==='')){error.value='经度和纬度请同时填写';return}
  if(picked.value&&(Math.abs(picked.value.longitude)>180||Math.abs(picked.value.latitude)>90)){error.value='坐标范围不正确';return}
  emit('save',{name:name.value.trim(),city:city.value.trim(),address:address.value.trim(),category:category.value,tags:list,notes:notes.value,sourceUrl:url.value.trim(),longitude:picked.value?.longitude??null,latitude:picked.value?.latitude??null,coordinateSystem:picked.value?'WGS84':null,...(props.place?{favorite:props.place.favorite,visited:!!props.place.visited}:{})})
}
</script>
<template><TravelModal :title="place?'编辑收藏地点':'收藏一个新地点'" eyebrow="SAVE A PLACE" :locked="busy" :error="apiError" @close="emit('close')"><form @submit.prevent="save"><div class="tw-modal-body"><div class="tw-field"><label for="tp-name">地点名称</label><div class="tw-input-action"><input id="tp-name" v-model="name" required maxlength="180" placeholder="想去的景点、餐厅或住处"/><button type="button" :disabled="searching||!searchAvailable||name.trim().length<2" @click="search"><Search :size="15"/>{{ searching?'搜索中':'搜索位置' }}</button></div><small>{{ searchAvailable?'按下搜索才查询已配置的地名服务。':'地名搜索尚未配置，仍可在地图上选点或填写真实坐标。' }}</small></div><p v-if="searchAvailable" class="tw-hint">搜索提供：{{ searchProvider }} · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>，请核对候选地点与坐标。</p><div v-if="results.length" class="tw-search-results"><button v-for="(result,index) in results" :key="index" type="button" @click="select(result)"><MapPin :size="16"/><span><b>{{ result.name||'地图地点' }}</b><small>{{ result.address }}</small></span></button></div><div class="tw-form-grid"><div class="tw-field"><label for="tp-city">城市</label><input id="tp-city" v-model="city" required maxlength="120" placeholder="例如：杭州"/></div><div class="tw-field"><label for="tp-category">分类</label><select id="tp-category" v-model="category"><option v-for="item in ['景点','美食','咖啡','住宿']" :key="item">{{ item }}</option></select></div></div><div class="tw-field"><label for="tp-address">详细地址</label><input id="tp-address" v-model="address" maxlength="300" placeholder="可留空，出发前再确认"/></div><div class="tw-field"><label for="tp-tags">标签</label><input id="tp-tags" v-model="tags" placeholder="用逗号分隔，例如：日落、博物馆"/></div><details class="tw-coordinate-section" :open="!!picked"><summary><MapPin :size="14"/>真实位置与地图选点<span>{{ picked?'已填写坐标':'尚未定位' }}</span></summary><div class="tw-form-grid"><div class="tw-field"><label for="tp-longitude">经度（WGS84）</label><input id="tp-longitude" v-model="longitude" type="number" min="-180" max="180" step="any"/></div><div class="tw-field"><label for="tp-latitude">纬度（WGS84）</label><input id="tp-latitude" v-model="latitude" type="number" min="-90" max="90" step="any"/></div></div><button class="tw-text" type="button" @click="showMap=!showMap">{{ showMap?'收起地图':'打开地图选点' }}</button><div v-if="showMap" class="tw-mini-map"><TravelMap :points="[]" pick :picked="picked" @pick="point=>{longitude=point.longitude;latitude=point.latitude}"/></div><p class="tw-hint">未填写坐标的地点仍会收藏；不会放到地图上的虚构位置。</p></details><div class="tw-field"><label for="tp-source">来源链接</label><input id="tp-source" v-model="url" type="url" maxlength="1500" placeholder="https://…"/></div><div class="tw-field"><label for="tp-notes">地点笔记</label><textarea id="tp-notes" v-model="notes" rows="3" maxlength="5000" placeholder="预约方式、喜欢的理由，或要留意的事情…"></textarea></div><p v-if="error" role="alert" class="tw-error">{{ error }}</p></div><footer class="tw-modal-footer"><button type="button" class="tw-button secondary" :disabled="busy" @click="emit('close')">取消</button><button class="tw-button primary" :disabled="busy">{{ busy?'保存中…':'保存地点' }}</button></footer></form></TravelModal></template>
